#!/usr/bin/env Rscript
# code/09_summit_match.R
# Task T032: Compute Spearman ρ and summit match percentage for top-ranked CREs
#
# Inputs:
#   - results/CRE_ranked_<stress>.md (generated by T018/T017)
#   - tracks/<stress>_CRE_signal.bw (generated by T031)
#
# Outputs:
#   - results/summit_match_stats.txt
#
# Requirements (SC-005):
#   - Compute Spearman correlation (ρ) between CRE rank (by q-value/|β₁|) and signal strength.
#   - Calculate % of summit matches within ±5 bp of the peak signal maximum.
#   - Flag if ρ < 0.8 OR match % < 90%.

library(data.table)
library(rtracklayer)
library(dplyr)
library(ggplot2)

# Configuration
args <- commandArgs(trailingOnly = TRUE)
if (length(args) < 1) {
  stop("Usage: Rscript code/09_summit_match.R <stress_condition>")
}
stress <- args[1]

# File paths
ranked_file <- file.path("results", paste0("CRE_ranked_", stress, ".md"))
bw_file <- file.path("tracks", paste0(stress, "_CRE_signal.bw"))
output_file <- file.path("results", "summit_match_stats.txt")

# Validation: Check inputs exist
if (!file.exists(ranked_file)) {
  stop(paste("Error: Ranked CRE file not found:", ranked_file))
}
if (!file.exists(bw_file)) {
  stop(paste("Error: BigWig track not found:", bw_file))
}

cat(sprintf("[T032] Starting summit match analysis for stress condition: %s\n", stress))
cat(sprintf("[T032] Input ranked file: %s\n", ranked_file))
cat(sprintf("[T032] Input BigWig file: %s\n", bw_file))

# 1. Load Ranked CREs
# The file is Markdown, likely with a header line. We need to parse the table.
# Assuming standard markdown table format: | chrom | start | end | summit | ...
lines <- readLines(ranked_file)
header_line_idx <- which(grepl("\\|\\s*chrom\\s*\\|", lines, ignore.case = TRUE))

if (length(header_line_idx) == 0) {
  stop("Error: Could not find header row in ranked file. Expected '| chrom | ...' format.")
}

# Extract data rows (skip header and separator line)
data_start <- header_line_idx[1] + 2
if (data_start > length(lines)) {
  stop("Error: No data rows found after header in ranked file.")
}
data_lines <- lines[data_start:length(lines)]
data_lines <- data_lines[!grepl("^\\|\\s*$", data_lines)] # Remove empty lines
data_lines <- data_lines[!grepl("^\\|\\s*-+\\s*\\|", data_lines)] # Remove separator if missed

# Parse markdown table
parse_md_row <- function(row) {
  # Split by |, remove empty strings, trim whitespace
  parts <- unlist(strsplit(row, "\\|"))
  parts <- parts[!grepl("^\\s*$", parts)]
  parts <- trimws(parts)
  return(parts)
}

cre_data <- do.call(rbind, lapply(data_lines, parse_md_row))
cre_df <- as.data.frame(cre_data, stringsAsFactors = FALSE)

# Determine column indices dynamically based on typical output
# Expected columns: chrom, start, end, summit_pos, tf, log2fc, beta1, qvalue
# We look for column names that match these patterns
col_names <- c("chrom", "start", "end", "summit", "tf", "log2fc", "beta1", "qvalue")
# Try to match headers from the first row of cre_df to expected names
# Assuming the first row of cre_df contains the headers from the markdown table
# Actually, in the parse above, the first row of cre_df IS the header row if we didn't skip it.
# Let's re-safely assign headers.

# Re-parse assuming the first non-empty line after header is the separator, then data
# But our logic above skipped the separator. So cre_df[1,] is the header.
headers <- cre_df[1, ]
cre_df <- cre_df[-1, ]

# Map headers to standard names (case insensitive)
headers_lower <- tolower(headers)
col_map <- c(
  chrom = which(headers_lower %in% c("chrom", "chromosome", "chr")),
  start = which(headers_lower %in% c("start", "start_pos")),
  end = which(headers_lower %in% c("end", "end_pos")),
  summit = which(headers_lower %in% c("summit", "summit_pos", "peak_center")),
  beta1 = which(headers_lower %in% c("beta1", "coeff", "coef")),
  qvalue = which(headers_lower %in% c("qvalue", "adj_p", "q_val"))
)

# Validate required columns
required <- c("chrom", "start", "end", "summit", "beta1", "qvalue")
missing <- required[is.na(col_map[required])]
if (length(missing) > 0) {
  stop(paste("Error: Missing required columns in ranked file:", paste(missing, collapse = ", ")))
}

# Rename columns
names(cre_df) <- headers
cre_df <- cre_df %>%
  mutate(
    chrom = .[[col_map["chrom"]]],
    start = as.numeric(.[[col_map["start"]]]),
    end = as.numeric(.[[col_map["end"]]]),
    summit = as.numeric(.[[col_map["summit"]]]),
    beta1 = as.numeric(.[[col_map["beta1"]]]),
    qvalue = as.numeric(.[[col_map["qvalue"]]])
  ) %>%
  select(chrom, start, end, summit, beta1, qvalue)

# Filter for significant CREs (FDR <= 0.05) as per task description
cre_df <- cre_df %>% filter(!is.na(qvalue) & qvalue <= 0.05)

if (nrow(cre_df) == 0) {
  warning("No significant CREs found (q <= 0.05) in the ranked file.")
  # Write empty result
  writeLines(c(
    "Summit Match Analysis Results",
    paste("Stress Condition:", stress),
    "Status: No significant CREs found",
    "Spearman Rho: NA",
    "Match Percentage: NA",
    "Flag: N/A (No data)"
  ), output_file)
  cat("[T032] No significant CREs found. Output written.\n")
  quit(status = 0)
}

# Sort by q-value then absolute beta1 to get "Top-Ranked" order
cre_df <- cre_df %>%
  arrange(qvalue, desc(abs(beta1))) %>%
  mutate(rank = row_number())

cat(sprintf("[T032] Loaded %d significant CREs (q <= 0.05).\n", nrow(cre_df)))

# 2. Load BigWig Signal
# We need the signal at the summit position for each CRE
bw <- import(bw_file)

# Extract signal at summit positions
# Create a GRanges for the summit points
summit_gr <- GRanges(
  seqnames = cre_df$chrom,
  ranges = IRanges(start = cre_df$summit, width = 1),
  strand = "*"
)

# Query the bigWig
# Note: rtracklayer::import with a GRanges returns the signal in the 'score' or 'signal' slot
signal_hits <- import(bw_file, which = summit_gr)

if (length(signal_hits) == 0) {
  stop("Error: No signal found in BigWig file at any summit positions.")
}

# Extract the signal value (usually stored in the 'score' or 'signal' metadata column)
# Depending on how bigWig was generated, it might be 'score' or just the value
signal_val <- mcols(signal_hits)$score
if (is.null(signal_val)) signal_val <- mcols(signal_hits)$signal
if (is.null(signal_val)) {
  # Fallback: if it's a simple RleList, we might need to extract differently, 
  # but import usually handles it. Let's assume score exists.
  stop("Error: Could not extract signal values from BigWig metadata.")
}

# Handle NA values (regions with no coverage)
if (any(is.na(signal_val))) {
  warning("Some summit positions have no signal (NA). These will be excluded from correlation.")
  valid_idx <- !is.na(signal_val)
  cre_df <- cre_df[valid_idx, ]
  signal_val <- signal_val[valid_idx]
}

cre_df$signal <- signal_val

# Ensure row alignment
if (nrow(cre_df) != length(signal_val)) {
  stop("Internal error: Row mismatch between CRE data and signal values.")
}

# 3. Compute Spearman Correlation (ρ)
# Correlation between Rank (1..N) and Signal Strength
rho <- cor(cre_df$rank, cre_df$signal, method = "spearman", use = "complete.obs")

# 4. Compute Summit Match Percentage (±5 bp)
# "Summit match" implies comparing the reported summit position to the 
# actual maximum signal position within the CRE region (start to end).
# We need to find the argmax of the signal in the CRE region for each CRE.

matches <- 0
total <- nrow(cre_df)

cat("[T032] Calculating summit matches (±5 bp)...\n")

for (i in 1:total) {
  row <- cre_df[i, ]
  region_gr <- GRanges(
    seqnames = row$chrom,
    ranges = IRanges(start = row$start, end = row$end),
    strand = "*"
  )
  
  # Extract signal profile for this region
  # This can be slow in a loop. For efficiency, we might batch, but for top-100 or so it's okay.
  # Optimization: If the bigWig is small, we can query all at once, but let's do per-CRE for accuracy.
  
  region_signal <- import(bw_file, which = region_gr)
  
  if (length(region_signal) == 0) next
  
  # Find the position of maximum signal
  # region_signal is a GRanges. We need the start position of the bin with max score.
  # If the bigWig has multiple bins in the region, we find the one with max score.
  max_idx <- which.max(mcols(region_signal)$score)
  max_pos <- start(region_signal)[max_idx]
  
  # Check if max_pos is within ±5 bp of the reported summit
  diff <- abs(max_pos - row$summit)
  if (diff <= 5) {
    matches <- matches + 1
  }
}

match_percentage <- (matches / total) * 100

# 5. Flags and Thresholds
rho_flag <- ifelse(rho >= 0.8, "PASS", "FAIL")
match_flag <- ifelse(match_percentage >= 90, "PASS", "FAIL")
overall_status <- ifelse(rho_flag == "PASS" && match_flag == "PASS", "PASS", "FAIL")

# 6. Write Output
output_lines <- c(
  "Summit Match Analysis Results",
  paste("Stress Condition:", stress),
  paste("Total Significant CREs Analyzed:", total),
  "",
  "Metrics:",
  paste("Spearman Rho (Rank vs Signal):", sprintf("%.4f", rho)),
  paste("Summit Match Percentage (±5 bp):", sprintf("%.2f%%", match_percentage)),
  paste("Match Count:", matches, "/", total),
  "",
  "Thresholds & Flags:",
  paste("Rho Threshold (>= 0.8):", rho_flag),
  paste("Match % Threshold (>= 90%):", match_flag),
  paste("Overall Status:", overall_status)
)

writeLines(output_lines, output_file)

cat(sprintf("[T032] Analysis Complete. Output written to %s\n", output_file))
cat(sprintf("[T032] Spearman Rho: %.4f (%s)\n", rho, rho_flag))
cat(sprintf("[T032] Match Percentage: %.2f%% (%s)\n", match_percentage, match_flag))

if (overall_status == "FAIL") {
  cat("[T032] WARNING: One or more thresholds not met. Check results/summit_match_stats.txt.\n")
}

# Exit successfully
quit(status = 0)
